 * Required by project CLAUDE.md for @sentry/nextjs@10 + Next 16.
 *
 * register() is called once per process start (server and edge separately).
 * onRequestError is the Next 16 hook for RSC + route-handler error capture.
 */

export async function register() {
  if (process.env.NEXT_RUNTIME === 'nodejs') {
    await import('./sentry.server.config')
  }
  if (process.env.NEXT_RUNTIME === 'edge') {
    await import('./sentry.edge.config')
  }
}

export { captureRequestError as onRequestError } from '@sentry/nextjs'

/**
 * Rate limiters — Upstash Ratelimit.
 *
 * Falls back to a permissive no-op limiter when UPSTASH_REDIS_REST_URL /
 * UPSTASH_REDIS_REST_TOKEN are absent (local dev without Redis).
 *
 * Production MUST have both env vars set or all limiters will always allow
 * requests — the startup check in lib/env.ts will warn in that case.
 */
import { logger } from '@/lib/logger'

// ─── Limiter interface (matches Upstash RatelimitResponse shape) ────────────
export interface RateLimitResponse {
  success: boolean
  limit: number
  remaining: number
  reset: number
}

export interface Limiter {
  limit: (identifier: string) => Promise<RateLimitResponse>
}

// ─── No-op fallback (used when Redis env vars absent) ───────────────────────
function makeNoop(name: string): Limiter {
  let warned = false
  return {
    async limit() {
      if (!warned) {
        logger.warn(
          { limiter: name },
          'rate-limit: UPSTASH_REDIS_REST_URL not set — limiter is permissive (dev mode)',
        )
        warned = true
      }
      return { success: true, limit: 9999, remaining: 9999, reset: Date.now() + 60_000 }
    },
  }
}

// ─── Real Upstash limiter factory ────────────────────────────────────────────
function makeUpstashLimiter(
  requests: number,
  windowSeconds: number,
  name: string,
): Limiter {
  const url = process.env.UPSTASH_REDIS_REST_URL
  const token = process.env.UPSTASH_REDIS_REST_TOKEN

  if (!url || !token) {
    return makeNoop(name)
  }

  // Sliding window via Upstash REST API — no Node.js SDK dependency needed.
  // Uses the MULTI/EXEC pattern: INCR + EXPIRE in one round-trip.
  return {
    async limit(identifier: string): Promise<RateLimitResponse> {
      const key = `rl:${name}:${identifier}`
      const now = Date.now()
      const windowMs = windowSeconds * 1_000

      try {
        // Pipeline: INCR key + EXPIRE key windowSeconds
        const pipelineRes = await fetch(`${url}/pipeline`, {
          method: 'POST',
          headers: {
            Authorization: `Bearer ${token}`,
            'Content-Type': 'application/json',
          },
          body: JSON.stringify([
            ['INCR', key],
            ['EXPIRE', key, windowSeconds],
          ]),
        })

        if (!pipelineRes.ok) {
          logger.warn({ name, status: pipelineRes.status }, 'rate-limit: Upstash pipeline error — allowing request')
          return { success: true, limit: requests, remaining: requests, reset: now + windowMs }
        }

        const results = await pipelineRes.json() as [{ result: number }, { result: number }]
        const count = results[0].result

        const remaining = Math.max(0, requests - count)
        const reset = now + windowMs

        if (count > requests) {
          return { success: false, limit: requests, remaining: 0, reset }
        }

        return { success: true, limit: requests, remaining, reset }
      } catch (err) {
        // On Redis error: fail open (allow) and log
        logger.error({ err, name }, 'rate-limit: Redis error — failing open')
        return { success: true, limit: requests, remaining: requests, reset: now + windowMs }
      }
    },
  }
}

// ─── Exported limiters ───────────────────────────────────────────────────────
// Adjust windows and limits per endpoint risk profile.

/** Generic authenticated API calls — 120 req/min per IP */
export const apiRatelimit = makeUpstashLimiter(120, 60, 'api')

/** Authenticated actions (CRUD) — 60 req/min per IP */
export const authedRatelimit = makeUpstashLimiter(60, 60, 'authed')

/** Expensive operations (AI generation, PDF export, reports) — 10 req/min */
export const expensiveRatelimit = makeUpstashLimiter(10, 60, 'expensive')

/** Login attempts — 10 per 15 minutes per IP (brute-force protection) */
export const loginRatelimit = makeUpstashLimiter(10, 900, 'login')

/** Signup attempts — 5 per 15 minutes per IP (spam protection) */
export const signupRatelimit = makeUpstashLimiter(5, 900, 'signup')

/** Forgot-password requests — 5 per 15 minutes per IP */
export const forgotPasswordRatelimit = makeUpstashLimiter(5, 900, 'forgot-password')

/** Public booking page reads — 60 req/min per IP */
export const publicBookingReadRatelimit = makeUpstashLimiter(60, 60, 'public-booking-read')

/** Public booking submissions — 10 per 10 minutes per IP */
export const publicBookingCreateRatelimit = makeUpstashLimiter(10, 600, 'public-booking-create')

/** Public consent form reads — 30 req/min per IP */
export const publicConsentReadRatelimit = makeUpstashLimiter(30, 60, 'public-consent-read')

/** Public consent form submissions — 5 per 10 minutes per IP */
export const publicConsentSubmitRatelimit = makeUpstashLimiter(5, 600, 'public-consent-submit')

/**
 * Email sender — Resend transactional email client.
 *
 * Falls back to a warning log when RESEND_API_KEY is absent (local dev).
 * In production, RESEND_API_KEY must be set or emails silently drop with a log.
 */
import { Resend } from 'resend'
import { renderAsync } from '@react-email/components'
import { logger } from '@/lib/logger'

export const FROM_EMAIL = process.env.RESEND_FROM_EMAIL ?? 'notifications@inkos.app'
export const REPLY_TO = process.env.RESEND_REPLY_TO ?? 'support@inkos.app'

// ─── Template registry ───────────────────────────────────────────────────────

export type EmailTemplate =
  | 'booking_confirmation'
  | 'booking_reminder_24h'
  | 'booking_reminder_2h'
  | 'deposit_received'
  | 'session_aftercare'
  | 'invoice_paid'
  | 'payment_failed'

// Per-template data shapes — typed so callers get compile-time errors on missing fields
interface BookingConfirmationData {
  studioName: string
  clientFirstName: string
  serviceName: string
  artistName: string
  scheduledAt: string   // ISO 8601
  endAt: string         // ISO 8601
  durationMin: number
  priceCents: number
  depositCents: number
  depositPaid: boolean
  bookingReference: string
  depositPaymentUrl?: string
}

interface BookingReminderData {
  studioName: string
  clientFirstName: string
  serviceName: string
  artistName: string
  scheduledAt: string
  bookingReference: string
}

interface DepositReceivedData {
  studioName: string
  clientFirstName: string
  serviceName: string
  depositCents: number
  bookingReference: string
}

interface InvoicePaidData {
  studioName: string
  clientFirstName: string
  amountCents: number
  invoiceId: string
  receiptUrl?: string
}

interface PaymentFailedData {
  studioName: string
  clientFirstName: string
  amountCents: number
  retryDate?: string
  updatePaymentUrl?: string
}

type TemplateDataMap = {
  booking_confirmation: BookingConfirmationData
  booking_reminder_24h: BookingReminderData
  booking_reminder_2h: BookingReminderData
  deposit_received: DepositReceivedData
  session_aftercare: BookingReminderData
  invoice_paid: InvoicePaidData
  payment_failed: PaymentFailedData
}

export interface SendEmailParams<T extends EmailTemplate> {
  to: string
  template: T
  data: TemplateDataMap[T]
}

// ─── Template subjects ───────────────────────────────────────────────────────
const SUBJECTS: Record<EmailTemplate, string> = {
  booking_confirmation: 'Your booking is confirmed',
  booking_reminder_24h: 'Reminder: Your appointment is tomorrow',
  booking_reminder_2h: 'Reminder: Your appointment is in 2 hours',
  deposit_received: 'Deposit received — you're all set',
  session_aftercare: 'Aftercare instructions for your session',
  invoice_paid: 'Payment confirmed',
  payment_failed: 'Action needed: Payment failed',
}

// ─── Lazy Resend client ──────────────────────────────────────────────────────
let _resend: Resend | null = null

function getResendClient(): Resend | null {
  const key = process.env.RESEND_API_KEY
  if (!key) return null
  if (!_resend) _resend = new Resend(key)
  return _resend
}

// ─── Template renderer ───────────────────────────────────────────────────────
async function renderTemplate(template: EmailTemplate, data: TemplateDataMap[EmailTemplate]): Promise<string> {
  switch (template) {
    case 'booking_confirmation': {
      const { BookingConfirmationEmail } = await import('./templates/booking-confirmation')
      const d = data as BookingConfirmationData
      const html = await renderAsync(
        BookingConfirmationEmail({
          ...d,
          scheduledAt: new Date(d.scheduledAt),
          endAt: new Date(d.endAt),
        }),
      )
      return html
    }
    case 'booking_reminder_24h':
    case 'booking_reminder_2h':
    case 'session_aftercare': {
      const { ReminderEmail } = await import('./templates/reminder-24h')
      const d = data as BookingReminderData
      const html = await renderAsync(
        ReminderEmail({
          ...d,
          scheduledAt: new Date(d.scheduledAt),
          variant: template === 'booking_reminder_2h' ? '2h' : template === 'session_aftercare' ? 'aftercare' : '24h',
        }),
      )
      return html
    }
    case 'deposit_received': {
      const { DepositReceiptEmail } = await import('./templates/deposit-receipt')
      const html = await renderAsync(DepositReceiptEmail(data as DepositReceivedData))
      return html
    }
    case 'invoice_paid':
    case 'payment_failed': {
      // Generic billing email using base layout
      const { BaseEmail, colors } = await import('./templates/_base')
      const { createElement } = await import('react')
      const { Text } = await import('@react-email/components')
      if (template === 'invoice_paid') {
        const d = data as InvoicePaidData
        const amountStr = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(d.amountCents / 100)
        const html = await renderAsync(
          createElement(BaseEmail, { preview: 'Payment confirmed', studioName: d.studioName },
            createElement(Text, { style: { color: colors.text, fontSize: '18px', fontWeight: '600', margin: '0 0 12px' } }, 'Payment confirmed'),
            createElement(Text, { style: { color: colors.textMuted, fontSize: '14px', margin: '0' } }, `${d.clientFirstName}, your payment of ${amountStr} has been received. Invoice: ${d.invoiceId}.`),
          ),
        )
        return html
      } else {
        const d = data as PaymentFailedData
        const amountStr = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(d.amountCents / 100)
        const html = await renderAsync(
          createElement(BaseEmail, { preview: 'Action needed: Payment failed', studioName: d.studioName },
            createElement(Text, { style: { color: colors.text, fontSize: '18px', fontWeight: '600', margin: '0 0 12px' } }, 'Payment failed'),
            createElement(Text, { style: { color: colors.textMuted, fontSize: '14px', margin: '0' } }, `${d.clientFirstName}, we were unable to process your payment of ${amountStr}. Please update your payment method to keep your subscription active.`),
          ),
        )
        return html
      }
    }
    default: {
      const _exhaustive: never = template
      throw new Error(`Unknown email template: ${String(_exhaustive)}`)
    }
  }
}

// ─── sendEmail ───────────────────────────────────────────────────────────────

export async function sendEmail<T extends EmailTemplate>(
  params: SendEmailParams<T>,
): Promise<{ id: string }> {
  const client = getResendClient()

  if (!client) {
    logger.warn(
      { to: params.to, template: params.template },
      'email skipped — RESEND_API_KEY not set (set it in .env.local)',
    )
    return { id: `noop-${Date.now()}` }
  }

  let html: string
  try {
    html = await renderTemplate(params.template, params.data as TemplateDataMap[EmailTemplate])
  } catch (err) {
    logger.error({ err, template: params.template }, 'email: template render failed')
    throw err
  }

  const { data, error } = await client.emails.send({
    from: FROM_EMAIL,
    replyTo: REPLY_TO,
    to: params.to,
    subject: SUBJECTS[params.template],
    html,
  })

  if (error) {
    logger.error({ error, to: params.to, template: params.template }, 'email: send failed')
    throw new Error(`Resend error: ${error.message}`)
  }

  logger.info({ id: data?.id, to: params.to, template: params.template }, 'email: sent')
  return { id: data?.id ?? `sent-${Date.now()}` }
}

