/**
 * Invoice Paid Email
 * Sent when: a subscription invoice is paid (Dodo Payments webhook)
 * Recipient: studio owner
 */

import { Text, Hr } from '@react-email/components'
import { BaseEmail, colors } from './_base'
import type { InvoicePaidData } from '@/lib/email/resend'

function formatCurrency(cents: number): string {
  return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(cents / 100)
}

export function InvoicePaidEmail({ studioName, clientFirstName, amountCents, invoiceId }: InvoicePaidData) {
  const preview = `Payment of ${formatCurrency(amountCents)} confirmed`

  return (
    <BaseEmail preview={preview} studioName={studioName}>
      <Text style={{ color: colors.text, fontSize: '22px', fontWeight: '600', margin: '0 0 8px' }}>
        Payment confirmed
      </Text>
      <Text style={{ color: colors.textMuted, fontSize: '14px', margin: '0 0 24px' }}>
        {clientFirstName}, your payment of {formatCurrency(amountCents)} has been received and your subscription is active.
      </Text>

      <Hr style={{ borderColor: colors.border, margin: '0 0 20px' }} />

      <Text style={{ color: colors.textMuted, fontSize: '12px', margin: '0', fontFamily: 'monospace' }}>
        Invoice: {invoiceId}
      </Text>
    </BaseEmail>
  )
}

export default InvoicePaidEmail

/**
 * Payment Failed Email
 * Sent when: a subscription payment fails (Dodo Payments webhook)
 * Recipient: studio owner
 */

import { Text, Hr } from '@react-email/components'
import { BaseEmail, colors } from './_base'
import type { PaymentFailedData } from '@/lib/email/resend'

function formatCurrency(cents: number): string {
  return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(cents / 100)
}

export function PaymentFailedEmail({
  studioName,
  clientFirstName,
  amountCents,
  updatePaymentUrl,
}: PaymentFailedData) {
  const preview = `Action needed: payment of ${formatCurrency(amountCents)} failed`

  return (
    <BaseEmail preview={preview} studioName={studioName}>
      <Text style={{ color: colors.text, fontSize: '22px', fontWeight: '600', margin: '0 0 8px' }}>
        Payment failed
      </Text>
      <Text style={{ color: colors.textMuted, fontSize: '14px', margin: '0 0 24px' }}>
        {clientFirstName}, we were unable to process your payment of {formatCurrency(amountCents)}. Please update your payment method to keep your subscription active.
      </Text>

      <Hr style={{ borderColor: colors.border, margin: '0 0 20px' }} />

      {updatePaymentUrl && (
        <a
          href={updatePaymentUrl}
          style={{
            display: 'inline-block',
            backgroundColor: colors.primary,
            color: '#ffffff',
            borderRadius: '8px',
            padding: '10px 24px',
            fontSize: '14px',
            fontWeight: '600',
            textDecoration: 'none',
          }}
        >
          Update payment method
        </a>
      )}
    </BaseEmail>
  )
}

export default PaymentFailedEmail
